/* Cep Finans: no analytics. Financial records remain in this browser; only requested market symbols are sent to price providers. */
const DB='cepFinans', DB_VERSION=6, STORE=['accounts','transactions'];
const BACKUP_STORES=['accounts','transactions','budgets','savingsGoals','goalContributions','recurringTransactions','cardProfiles','cardPurchases','cardStatements','debts','debtSettlements','loans','investmentAssets','assetValuations'];
let db, state={accounts:[],transactions:[],budgets:[],goals:[],goalContributions:[],recurring:[],debts:[],loans:[],investments:[]}, txFilter='all', txQuery='';
const $=s=>document.querySelector(s), money=n=>FinanceCore.format(Math.round(Number(n||0)*100));
const dateISO=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
function toast(s){const t=$('#toast');t.textContent=s;t.style.display='block';setTimeout(()=>t.style.display='none',2800)}
function announceConnection(){toast(navigator.onLine?'İnternet bağlantısı yeniden kuruldu.':'Çevrimdışısınız — kayıtlar bu cihazda çalışmaya devam eder.')}
function quantityMicros(value){const raw=String(value??'').trim().replace(/\s/g,'').replace(',','.');if(!/^\d+(\.\d{1,6})?$/.test(raw))throw new Error('Miktar en fazla 6 ondalık basamakla girilmeli.');const [whole,decimal='']=raw.split('.'),result=Number(whole)*1000000+Number((decimal+'000000').slice(0,6));if(!Number.isSafeInteger(result)||result<=0)throw new Error('Geçerli bir miktar girin.');return result}
function investmentValueMinor(asset,priceMinor=asset.currentPriceMinor){if(!Number.isSafeInteger(priceMinor)||priceMinor<0)return null;return Number((BigInt(asset.quantityMicros)*BigInt(priceMinor))/1000000n)}
function investmentTypeName(type){return ({gold:'Altın',fund:'Fon',stock:'Hisse',crypto:'Kripto',currency:'Döviz'})[type]||'Yatırım'}
function investmentForm(assetId){const existing=assetId?state.investments.find(asset=>asset.id===assetId):null;if(assetId&&!existing)return;const quantity=existing?(existing.quantityMicros/1000000).toLocaleString('tr-TR',{maximumFractionDigits:6,useGrouping:false}):'',cost=existing?(existing.costPriceMinor/100).toFixed(2).replace('.',','):'';show(`<h2 class="formTitle">${existing?'Yatırımı düzenle':'Yatırım ekle'}</h2><p class="formHint">Alış fiyatı sizin girdiğiniz maliyettir. Güncel fiyat, güncelleme yaptığınızda dış kaynaktan alınır.</p><label class="field">Tür<select name="type">${[['gold','Altın (gram)'],['fund','Fon'],['stock','Hisse'],['crypto','Kripto'],['currency','Döviz']].map(([value,label])=>`<option value="${value}" ${existing?.type===value?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">Ad<input required name="name" maxlength="80" placeholder="Örn. Gram altın" value="${esc(existing?.name||'')}"></label><label class="field">Miktar<input required name="quantity" type="text" inputmode="decimal" placeholder="Örn. 3" value="${quantity}"></label><label class="field">Birim alış fiyatınız (TL)<input required name="costPrice" type="text" inputmode="decimal" placeholder="Örn. 5.000,00" value="${cost}"></label><label class="field">Veri sembolü (fon/hisse/kripto/döviz için)<input name="symbol" maxlength="30" placeholder="Örn. BTC-USD, AAPL, USD" value="${esc(existing?.symbol||'')}"></label><div class="formActions"><button>Kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async f=>{try{const type=f.get('type'),name=String(f.get('name')||'').trim(),quantityMicrosValue=quantityMicros(f.get('quantity')),costPriceMinor=FinanceCore.minor(f.get('costPrice')),symbol=String(f.get('symbol')||'').trim().toUpperCase();if(!name||costPriceMinor<0)throw new Error('Geçerli yatırım bilgileri girin.');if(type!=='gold'&&!symbol)throw new Error('Bu yatırım türü için veri sembolü gerekli.');const stalePrice=existing&&((existing.type!==type)||(existing.symbol!==symbol)),record={id:existing?.id||id(),schemaVersion:1,type,name,quantityMicros:quantityMicrosValue,costPriceMinor,symbol,currency:'TRY',createdAt:existing?.createdAt||dateISO(),updatedAt:dateISO()};if(existing&&!stalePrice&&Number.isSafeInteger(existing.currentPriceMinor)){record.currentPriceMinor=existing.currentPriceMinor;record.currentPriceDate=existing.currentPriceDate}await put('investmentAssets',record);await load();if(navigator.onLine&&(!existing||stalePrice))refreshInvestment(record).then(load).catch(console.warn);toast(existing?'Yatırım güncellendi':'Yatırım eklendi; güncel fiyat alınıyor.')}catch(error){toast(error.message||'Yatırım kaydedilemedi.')}})}
async function marketFetch(url,options={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),8000);try{return await fetch(url,{...options,signal:controller.signal})}catch(error){if(error.name==='AbortError')throw new Error('Fiyat sağlayıcısı zamanında yanıt vermedi.');throw error}finally{clearTimeout(timer)}}
async function refreshInvestment(asset){let priceMinor;if(asset.type==='gold'){const response=await marketFetch('https://api.goldprice.dev/v1/carat?currency=TRY',{referrerPolicy:'no-referrer'});if(!response.ok)throw new Error('Altın fiyatı alınamadı.');const data=await response.json();priceMinor=FinanceCore.marketPriceMinor(data.price_gram_24k)}else if(asset.type==='currency'){const response=await marketFetch(`https://api.frankfurter.dev/v1/latest?base=${encodeURIComponent(asset.symbol)}&symbols=TRY`,{referrerPolicy:'no-referrer'});if(!response.ok)throw new Error('Döviz kuru alınamadı.');const data=await response.json();priceMinor=FinanceCore.marketPriceMinor(data.rates?.TRY)}else{const source=`https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(asset.symbol)}?range=1d&interval=1d`,response=await marketFetch(`https://proxy.cors.dev/${source}`,{credentials:'omit',referrerPolicy:'no-referrer'});if(!response.ok)throw new Error('Piyasa verisi alınamadı.');const data=await response.json(),meta=data.chart?.result?.[0]?.meta,rawPrice=meta?.regularMarketPrice;if(!Number.isFinite(rawPrice))throw new Error('Güncel fiyat bulunamadı.');let quoteMinor=FinanceCore.marketPriceMinor(rawPrice);if(meta.currency&&meta.currency!=='TRY'){const fx=await marketFetch(`https://api.frankfurter.dev/v1/latest?base=${encodeURIComponent(meta.currency)}&symbols=TRY`,{referrerPolicy:'no-referrer'});if(!fx.ok)throw new Error('Döviz dönüşümü alınamadı.');const rateMinor=FinanceCore.marketPriceMinor((await fx.json()).rates?.TRY);quoteMinor=Number((BigInt(quoteMinor)*BigInt(rateMinor))/100n)}priceMinor=quoteMinor}const valuation={id:id(),assetId:asset.id,priceMinor,date:dateISO(),fetchedAt:new Date().toISOString(),source:asset.type==='gold'?'goldprice.dev':asset.type==='currency'?'frankfurter.dev':'Yahoo Finance'};await put('assetValuations',valuation);await put('investmentAssets',{...asset,currentPriceMinor:priceMinor,currentPriceDate:dateISO(),updatedAt:dateISO()})}
async function refreshInvestments(){if(!navigator.onLine){toast('Fiyat güncellemesi için internet bağlantısı gerekli.');return}if(!state.investments.length){toast('Önce bir yatırım ekleyin.');return}let completed=0;for(const asset of state.investments){try{await refreshInvestment(asset);completed++}catch(error){console.warn(error)}}await load();toast(completed?`${completed} yatırımın fiyatı güncellendi`:'Fiyat alınamadı; sembolleri kontrol edin.')}
async function deleteInvestment(assetId){const asset=state.investments.find(item=>item.id===assetId);if(!asset||!confirm(`${asset.name} yatırımı silinsin mi? Bu işlem geri alınamaz.`))return;await remove('investmentAssets',assetId);for(const valuation of await all('assetValuations'))if(valuation.assetId===assetId)await remove('assetValuations',valuation.id);await load();toast('Yatırım silindi')}
function renderInvestments(){const rows=state.investments.map(asset=>{const cost=investmentValueMinor(asset,asset.costPriceMinor),current=investmentValueMinor(asset),profit=current===null?null:current-cost,quantity=(asset.quantityMicros/1000000).toLocaleString('tr-TR',{maximumFractionDigits:6}),updated=asset.currentPriceDate?` • ${fmtDate(asset.currentPriceDate)}`:'',unitPrice=Number.isSafeInteger(asset.currentPriceMinor)?money(asset.currentPriceMinor/100):null,actions=`<button type="button" class="textButton" data-investment-edit="${asset.id}">Düzenle</button><button type="button" class="textButton" data-investment-delete="${asset.id}">Sil</button>`;return `<div class="budget-row"><b><span>${esc(asset.name)} <small>${investmentTypeName(asset.type)} • ${quantity} adet</small></span><span>${current===null?'Fiyat bekliyor':money(current/100)}</span></b><small>${current===null?`Alış maliyeti: ${money(cost/100)}`:`${quantity} × ${unitPrice} = ${money(current/100)} • Maliyet: ${money(cost/100)} • ${profit>=0?'Kâr':'Zarar'}: ${money(Math.abs(profit)/100)}${updated}`}</small>${actions}</div>`}).join('');return `<div class="sectionHead"><h3>Yatırımlar</h3><button type="button" class="textButton" data-investment-form>＋ Ekle</button></div>${rows||'<div class="budget-row"><b>Henüz yatırım yok</b><small>Altın, fon, hisse, kripto veya döviz ekleyin.</small></div>'}<button type="button" class="textButton" data-investment-refresh>↻ Fiyatları güncelle</button>`}
function settleDebtForm(debtId){const debt=[...state.debts,...state.loans].find(d=>d.id===debtId);if(!debt||debt.active===false)return;show(`<h2 class="formTitle">Vade / tahsilat işle</h2><p class="formHint">Önce gerçek para hareketini uygulamada kaydedin. Bu adım yalnızca borç veya alacak planındaki kalan tutarı uzlaştırır.</p><p class="formHint">${esc(debt.name)} — kalan ${money(debt.remainingMinor/100)}</p><label class="field">İşlenen tutar (TL)<input required name="amount" type="text" inputmode="decimal" placeholder="0,00"></label><label class="field">Tarih<input required name="date" type="date" value="${dateISO()}"></label><div class="formActions"><button>Kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async f=>{try{const amountMinor=FinanceCore.minor(f.get('amount')),settlementDate=FinanceCore.date(f.get('date'));if(amountMinor<=0||amountMinor>debt.remainingMinor)throw new Error('Tutar sıfırdan büyük olmalı ve kalan tutarı aşmamalı.');const remainingMinor=debt.remainingMinor-amountMinor,remainingInstallments=remainingMinor===0?0:Math.max(1,Math.ceil(remainingMinor/debt.monthlyPaymentMinor));await put('debts',{...debt,remainingMinor,remainingInstallments,nextDueDate:remainingMinor===0?debt.nextDueDate:FinanceCore.addMonths(settlementDate,1),active:remainingMinor>0,updatedAt:dateISO()});await put('debtSettlements',{id:id(),schemaVersion:1,debtId,amountMinor,date:settlementDate,direction:debt.direction||'outgoing'});await load();toast(remainingMinor===0?'Kayıt kapatıldı':'Kalan tutar ve sonraki vade güncellendi')}catch(error){toast(error.message||'Vade işlenemedi.')}})}
function postRecurringForm(recurringId){const recurring=state.recurring.find(r=>r.id===recurringId);if(!recurring||recurring.active===false)return;const account=state.accounts.find(a=>a.id===recurring.accountId);if(!account||account.archivedAt){toast('Bu düzenli ödeme için aktif bir hesap seçin.');return}show(`<h2 class="formTitle">Düzenli ödemeyi işle</h2><p class="formHint">Bu işlem gerçek gider kaydı oluşturur ve sonraki vade tarihini ilerletir.</p><p class="formHint">${esc(recurring.name)} — ${money(recurring.amountMinor/100)}</p><label class="field">Tarih<input required name="date" type="date" value="${recurring.nextDueDate}"></label><div class="formActions"><button>Ödemeyi kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async f=>{try{const date=FinanceCore.date(f.get('date')),postings=FinanceCore.ledger([{accountId:recurring.accountId,amountMinor:-recurring.amountMinor},{accountId:'expense',amountMinor:recurring.amountMinor}]).map(p=>({...p,amount:p.amountMinor/100}));await put('transactions',{id:id(),schemaVersion:2,date,note:recurring.name,category:recurring.category,postings,planned:false,recurringId});await put('recurringTransactions',{...recurring,nextDueDate:FinanceCore.nextOccurrence(date,recurring.frequency),updatedAt:dateISO()});await load();toast('Düzenli ödeme işlendi')}catch(error){toast(error.message||'Ödeme kaydedilemedi.')}})}
function editRecurringForm(recurringId){const recurring=state.recurring.find(r=>r.id===recurringId);if(!recurring)return;const accounts=state.accounts.filter(a=>!a.archivedAt&&a.type!=='card');if(!accounts.length){toast('Önce aktif bir banka hesabı ekleyin.');return}const accountOptions=accounts.map(a=>`<option value="${a.id}" ${a.id===recurring.accountId?'selected':''}>${esc(a.name)}</option>`).join(''),amount=(recurring.amountMinor/100).toFixed(2).replace('.',',');show(`<h2 class="formTitle">Düzenli ödemeyi düzenle</h2><label class="field">Ad<input required name="name" maxlength="80" value="${esc(recurring.name)}"></label><label class="field">Tutar (TL)<input required name="amount" type="text" inputmode="decimal" value="${amount}"></label><label class="field">Kategori<select name="category">${['Fatura','Yemek','Ulaşım','Diğer'].map(c=>`<option ${c===recurring.category?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">Ödeme hesabı<select name="accountId">${accountOptions}</select></label><label class="field">Sıklık<select name="frequency">${[['monthly','Aylık'],['weekly','Haftalık'],['quarterly','3 aylık'],['yearly','Yıllık']].map(([value,label])=>`<option value="${value}" ${value===recurring.frequency?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">Sonraki ödeme tarihi<input required name="nextDueDate" type="date" value="${recurring.nextDueDate}"></label><label class="field">Plan etkin mi?<input name="active" type="checkbox" ${recurring.active!==false?'checked':''}></label><div class="formActions"><button>Kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async f=>{try{const amountMinor=FinanceCore.minor(f.get('amount'));if(amountMinor<=0)throw new Error('Tutar sıfırdan büyük olmalı.');await put('recurringTransactions',{...recurring,name:String(f.get('name')||'').trim(),amountMinor,category:f.get('category'),accountId:f.get('accountId'),frequency:f.get('frequency'),nextDueDate:FinanceCore.date(f.get('nextDueDate')),active:f.get('active')==='on',updatedAt:dateISO()});await load();toast(f.get('active')==='on'?'Düzenli ödeme güncellendi':'Düzenli ödeme durduruldu')}catch(error){toast(error.message||'Düzenli ödeme güncellenemedi.')}})}
function splitTransactionForm(){const accounts=state.accounts.filter(a=>!a.archivedAt);if(!accounts.length){toast('Önce aktif bir hesap veya kart ekleyin.');return}const options=accounts.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join(''),categories=['Market','Yemek','Ulaşım','Fatura','Eğlence','Sağlık','Diğer'];show(`<h2 class="formTitle">Harcama böl</h2><p class="formHint">Aynı ödeme içindeki kategorileri ayrı tutarlarla kaydedin. Boş satırlar hesaba katılmaz.</p><label class="field">Tarih<input required name="date" type="date" value="${dateISO()}"></label><label class="field">Ödeme hesabı / kart<select required name="from">${options}</select></label><label class="field">Açıklama<input name="note" maxlength="140" placeholder="Örn. Market alışverişi"></label>${[0,1,2].map(i=>`<div class="splitRow"><label class="field">Kategori<select name="category${i}">${categories.map(c=>`<option>${c}</option>`).join('')}</select></label><label class="field">Tutar (TL)<input name="amount${i}" type="text" inputmode="decimal" placeholder="0,00"></label></div>`).join('')}<div class="formActions"><button>Kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async f=>{try{const parts=[0,1,2].map(i=>({category:f.get(`category${i}`),amountMinor:FinanceCore.minor(f.get(`amount${i}`)||0)})).filter(x=>x.amountMinor>0);if(parts.length<2)throw new Error('En az iki kategori ve tutar girin.');const date=FinanceCore.date(f.get('date')),source=f.get('from'),note=String(f.get('note')||'').trim(),groupId=id();for(let i=0;i<parts.length;i++){const part=parts[i],postings=FinanceCore.ledger([{accountId:source,amountMinor:-part.amountMinor},{accountId:'expense',amountMinor:part.amountMinor}]).map(p=>({...p,amount:p.amountMinor/100}));await put('transactions',{id:id(),schemaVersion:2,date,note:note||'Bölünmüş harcama',category:part.category,postings,planned:false,splitGroup:groupId,splitIndex:i+1,splitCount:parts.length})}await load();toast(`${parts.length} kategoriye bölünmüş harcama kaydedildi`)}catch(error){toast(error.message||'Bölünmüş harcama kaydedilemedi.')}})}
function openDB(){return new Promise((ok,no)=>{const r=indexedDB.open(DB,DB_VERSION);r.onupgradeneeded=()=>{const d=r.result,tx=r.transaction;if(!d.objectStoreNames.contains('accounts'))d.createObjectStore('accounts',{keyPath:'id'});if(!d.objectStoreNames.contains('transactions'))d.createObjectStore('transactions',{keyPath:'id'});const transactions=tx.objectStore('transactions');if(!transactions.indexNames.contains('byDate'))transactions.createIndex('byDate','date');for(const name of ['profiles','categories','budgets','schedules','auditRecords','appSettings','cardProfiles','cardPurchases','cardStatements','recurringTransactions','savingsGoals','goalContributions','debts','debtSettlements','loans','investmentAssets','assetValuations'])if(!d.objectStoreNames.contains(name))d.createObjectStore(name,{keyPath:'id'});};r.onsuccess=()=>{db=r.result;ok()};r.onerror=()=>no(r.error)})}
function all(store){return new Promise((ok,no)=>{const r=db.transaction(store).objectStore(store).getAll();r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)})}
function put(store,item){return new Promise((ok,no)=>{const r=db.transaction(store,'readwrite').objectStore(store).put(item);r.onsuccess=ok;r.onerror=()=>no(r.error)})}
function remove(store,key){return new Promise((ok,no)=>{const r=db.transaction(store,'readwrite').objectStore(store).delete(key);r.onsuccess=ok;r.onerror=()=>no(r.error)})}
function clear(store){return new Promise((ok,no)=>{const r=db.transaction(store,'readwrite').objectStore(store).clear();r.onsuccess=ok;r.onerror=()=>no(r.error)})}
function replaceCoreData(data){return new Promise((ok,no)=>{const tx=db.transaction(BACKUP_STORES,'readwrite');try{for(const storeName of BACKUP_STORES){const store=tx.objectStore(storeName);store.clear();for(const item of data[storeName]||[])store.put(item)}tx.oncomplete=()=>ok();tx.onerror=()=>no(tx.error||new Error('Geri yükleme yazılamadı.'));tx.onabort=()=>no(tx.error||new Error('Geri yükleme iptal edildi.'))}catch(error){tx.abort();no(error)}})}
const id=()=>crypto.randomUUID();
function entryAmount(p){return Number.isSafeInteger(p.amountMinor)?p.amountMinor/100:Number(p.amount||0)}
function accountBalance(a){return state.transactions.filter(t=>t.date<=dateISO()&&t.postings.some(p=>p.accountId===a.id)).reduce((n,t)=>n+t.postings.filter(p=>p.accountId===a.id).reduce((x,p)=>x+entryAmount(p),0),Number(a.opening||0))}
function isLiquidAccount(a){return ['bank','cash','savings','wallet','prepaid'].includes(a.type)}
function accountName(i){return i==='expense'?'Gider':i==='income'?'Gelir':state.accounts.find(a=>a.id===i)?.name||'Bilinmeyen hesap'}
async function migrateCardLimits(){let changed=false;for(const account of state.accounts.filter(a=>a.type==='card'&&!Number.isSafeInteger(a.creditLimitMinor))){let creditLimitMinor=FinanceCore.minor(account.opening||0);await put('accounts',{...account,opening:0,openingMinor:0,creditLimitMinor,openingOutstandingMinor:0,expenseRecognition:'installment',legacyLimitMigrated:true});changed=true}return changed}
async function load(){state.accounts=await all('accounts');if(await migrateCardLimits())state.accounts=await all('accounts');state.transactions=await all('transactions');state.budgets=await all('budgets');state.goals=await all('savingsGoals');state.goalContributions=await all('goalContributions');state.recurring=await all('recurringTransactions');state.debts=await all('debts');state.loans=await all('loans');state.investments=await all('investmentAssets');state.transactions.sort((a,b)=>b.date.localeCompare(a.date));render()}
function txType(t){return t.postings.some(p=>p.accountId==='expense')?'expense':t.postings.some(p=>p.accountId==='income')?'income':'transfer'}
function transactionMatches(t){const query=txQuery.trim().toLocaleLowerCase('tr-TR');if(!query)return true;const searchable=[t.note,t.payee,t.category,...(t.tags||[]),t.date,...t.postings.map(p=>accountName(p.accountId))].join(' ').toLocaleLowerCase('tr-TR');return searchable.includes(query)}
function cardCycleHint(account){if(!account.closingDay)return 'Ekstre kesim günü tanımlanmadı';const cycle=FinanceCore.cardCycleWithDueOffset(dateISO(),account.closingDay,10,Boolean(account.closingDayPurchasesNext));return `Kesim: ${account.closingDay}. gün • Son ödeme: ${fmtDate(cycle.dueDate)}`}
function cardStatementPreview(account){if(!account.closingDay)return null;const cycles=new Map();for(const transaction of state.transactions){const cardPosting=transaction.postings.find(posting=>posting.accountId===account.id);if(!cardPosting)continue;const amountMinor=Math.round(entryAmount(cardPosting)*100);if(amountMinor>=0)continue;const cycle=FinanceCore.cardCycleWithDueOffset(transaction.date,account.closingDay,10,Boolean(account.closingDayPurchasesNext)),current=cycles.get(cycle.closingDate)||{closingDate:cycle.closingDate,dueDate:cycle.dueDate,purchaseMinor:0};current.purchaseMinor+=Math.abs(amountMinor);cycles.set(cycle.closingDate,current)}const candidates=[...cycles.values()].filter(cycle=>cycle.closingDate<=dateISO()).sort((a,b)=>b.closingDate.localeCompare(a.closingDate));if(!candidates.length)return null;const statement=candidates[0],payments=state.transactions.filter(transaction=>transaction.date>=statement.closingDate&&transaction.date<=statement.dueDate).reduce((total,transaction)=>{const posting=transaction.postings.find(entry=>entry.accountId===account.id);return total+(posting&&entryAmount(posting)>0?Math.round(entryAmount(posting)*100):0)},0);return {...statement,paidMinor:payments,outstandingMinor:Math.max(0,statement.purchaseMinor-payments)}}
function typeMeta(t){let type=txType(t);return type==='expense'?['↑','expense']:type==='income'?['↓','income']:['↔','transfer']}
function render(){const visibleAccounts=state.accounts.filter(a=>!a.archivedAt&&a.includeInTotals!==false),total=visibleAccounts.reduce((n,a)=>n+accountBalance(a),0),month=dateISO().slice(0,7),mTx=state.transactions.filter(t=>t.date.startsWith(month)&&(!t.planned||t.date<=dateISO()));let income=mTx.filter(t=>txType(t)==='income').reduce((n,t)=>n+Math.abs(entryAmount(t.postings.find(p=>p.accountId==='income')||{})),0),expense=mTx.filter(t=>txType(t)==='expense').reduce((n,t)=>n+Math.abs(entryAmount(t.postings.find(p=>p.accountId==='expense')||{})),0),set=(s,v)=>{let e=$(s);if(e)e.textContent=v};set('#netTotal',money(total));set('#accountCount',visibleAccounts.length?`${visibleAccounts.length} hesap / kart`:'Henüz hesap yok');set('#monthIncome',money(income));set('#monthExpense',money(expense));set('#monthBalance',money(income-expense));set('#analyticsTotal',money(income-expense));set('#analyticsIncome',money(income));set('#analyticsExpense',money(expense));set('#budgetSpent',money(expense));
 $('#accountsList').innerHTML=state.accounts.length?state.accounts.filter(a=>!a.archivedAt).map(a=>{let balance=accountBalance(a),isCard=a.type==='card',debt=Math.max(0,-balance),limit=(a.creditLimitMinor||0)/100,statement=isCard?cardStatementPreview(a):null,minBaseMinor=statement?statement.outstandingMinor:Math.round(debt*100),minPayment=isCard?FinanceCore.minimumCardPayment(minBaseMinor,a.creditLimitMinor||0):null,summary=isCard?`${money(debt)} borç • ${money(Math.max(0,limit-debt))} kullanılabilir • ${statement?`Dönem: ${money(statement.outstandingMinor/100)} • `:''}Asgari: ${money(minPayment.amountMinor/100)}`:money(balance);return `<div class="accountCard ${isCard?'cardType':''}" data-account-id="${a.id}" tabindex="0" role="button" aria-label="${esc(a.name)} hesabını düzenle"><div class="accountLeft"><span class="accountIcon">${isCard?'▣':'⌁'}</span><div><b>${esc(a.name)}</b><small>${isCard?cardCycleHint(a):(a.institution?esc(a.institution)+' • ':'')+'Banka hesabı'}</small></div></div><span class="accountAmount">${summary}</span></div>`}).join(''):'<p>Gösterilecek aktif hesap yok.</p>';
 let visible=state.transactions.filter(t=>(txFilter==='all'||txType(t)===txFilter)&&transactionMatches(t)),ledger=visible.length?visible.map(t=>{let [icon,type]=typeMeta(t),amount=Math.abs(entryAmount(t.postings.find(p=>p.accountId==='expense'||p.accountId==='income')||t.postings[0]||{}));return `<button class="txItem" data-edit-id="${t.id}" aria-label="${esc(t.note||'Hareket')} hareketini düzenle"><span class="txLeft"><span class="txIcon ${type}">${icon}</span><span><b>${esc(t.note||'İsimsiz hareket')}</b><small>${fmtDate(t.date)} • ${t.category||t.postings.map(p=>esc(accountName(p.accountId))).join(' ↔ ')}</small></span></span><span class="txAmount ${type==='expense'?'expense':type==='income'?'income':''}">${type==='expense'?'-':type==='income'?'+':''}${money(amount)} ›</span></button>`}).join(''):'<p>Bu ölçütte hareket yok.</p>';$('#transactionsList').innerHTML=ledger;$('#transactionsListFull').innerHTML=ledger;renderCategories(mTx,expense);renderForecast();renderBudgets(expense);renderRecurring()}
function renderRecurring(){let element=$('#recurringList'),labels={daily:'Günlük',weekly:'Haftalık',biweekly:'İki haftada bir',monthly:'Aylık',quarterly:'3 aylık',semiannual:'6 aylık',yearly:'Yıllık'};if(!element)return;let recurringHtml=state.recurring.length?state.recurring.filter(r=>r.active!==false).map(r=>`<div class="budget-row" data-recurring-post="${r.id}" tabindex="0" role="button"><b><span>${esc(r.name)}</span><span>${money(r.amountMinor/100)}</span></b><small>${labels[r.frequency]||'Özel'} • Sonraki tarih: ${fmtDate(r.nextDueDate)} • İşlemek için dokunun</small><button type="button" class="textButton" data-recurring-edit="${r.id}">Düzenle</button></div>`).join(''):'<div class="budget-row"><b>Henüz düzenli ödeme yok</b><small>Abonelik, kira veya fatura ekleyin.</small></div>',obligations=[...state.debts,...state.loans].filter(d=>d.active!==false),debtHtml=obligations.length?obligations.map(d=>`<div class="budget-row" data-debt-settle="${d.id}" tabindex="0" role="button"><b><span>${esc(d.name)}</span><span>${money(d.monthlyPaymentMinor/100)} / ay</span></b><small>${d.direction==='incoming'?'Tahsil edilecek alacak':'Ödenecek borç'} • Kalan: ${money(d.remainingMinor/100)} • ${d.remainingInstallments} vade • İşlemek için dokunun</small></div>`).join(''):'<div class="budget-row"><b>Henüz borç, kredi veya alacak yok</b><small>Planlamak için bir kayıt ekleyin.</small></div>';element.innerHTML=`${renderInvestments()}<div class="sectionHead"><h3>Düzenli ödemeler</h3></div>${recurringHtml}<div class="sectionHead"><h3>Borçlar ve alacaklar</h3><button type="button" class="textButton" data-debt-form>＋ Ekle</button></div>${debtHtml}`;element.querySelector('[data-investment-form]').onclick=investmentForm;element.querySelector('[data-investment-refresh]').onclick=refreshInvestments;element.querySelectorAll('[data-investment-edit]').forEach(button=>button.onclick=()=>investmentForm(button.dataset.investmentEdit));element.querySelectorAll('[data-investment-delete]').forEach(button=>button.onclick=()=>deleteInvestment(button.dataset.investmentDelete))}
function debtForm(){show(`<h2 class="formTitle">Borç / alacak planı ekle</h2><p class="formHint">Bu kayıt nakit tahminine planlı giriş veya çıkış ekler. Gerçek para hareketini ayrıca kaydedin.</p><label class="field">Tür<select name="direction"><option value="outgoing">Ödenecek borç / kredi</option><option value="incoming">Tahsil edilecek alacak</option></select></label><label class="field">Kişi / kurum / ad<input required name="name" maxlength="80" placeholder="Örn. Taşıt kredisi"></label><label class="field">Kalan tutar (TL)<input required name="remaining" type="text" inputmode="decimal" placeholder="0,00"></label><label class="field">Aylık tahsilat / ödeme (TL)<input required name="monthlyPayment" type="text" inputmode="decimal" placeholder="0,00"></label><label class="field">Kalan ödeme adedi<input required name="remainingInstallments" type="number" min="1" max="600" inputmode="numeric" value="12"></label><label class="field">İlk vade tarihi<input required name="nextDueDate" type="date" value="${dateISO()}"></label><div class="formActions"><button>Kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async f=>{try{let name=String(f.get('name')||'').trim(),remainingMinor=FinanceCore.minor(f.get('remaining')),monthlyPaymentMinor=FinanceCore.minor(f.get('monthlyPayment')),remainingInstallments=Math.max(1,Number(f.get('remainingInstallments'))||0),direction=f.get('direction');if(!name||remainingMinor<=0||monthlyPaymentMinor<=0)throw new Error('Geçerli tutarlar girin.');await put('debts',{id:id(),schemaVersion:2,name,direction,remainingMinor,monthlyPaymentMinor,remainingInstallments,nextDueDate:FinanceCore.date(f.get('nextDueDate')),active:true,createdAt:dateISO()});await load();toast(direction==='incoming'?'Alacak planlamaya eklendi':'Borç / kredi planlamaya eklendi')}catch(error){toast(error.message||'Kayıt eklenemedi.')}})}
function renderBudgets(expense){let month=dateISO().slice(0,7),spentByCategory={};state.transactions.filter(t=>txType(t)==='expense'&&t.date.startsWith(month)&&(!t.planned||t.date<=dateISO())).forEach(t=>{let c=t.category||'Diğer';spentByCategory[c]=(spentByCategory[c]||0)+Math.abs(entryAmount(t.postings.find(p=>p.accountId==='expense')||{}))});let budgets=state.budgets.filter(b=>b.active!==false),totalLimit=budgets.reduce((n,b)=>n+b.limitMinor,0),totalSpent=budgets.reduce((n,b)=>n+(spentByCategory[b.category]||0),0),percent=totalLimit?Math.round(totalSpent/totalLimit*100):0;let percentElement=$('#budgetPercent'),summary=$('#budgetSummary');if(percentElement)percentElement.textContent=`${percent}%`;if(summary)summary.textContent=totalLimit?`${money(Math.max(0,(totalLimit-totalSpent)/100))} kaldı`:'Bütçe tanımla';$('#budgetList').innerHTML=budgets.length?budgets.map(b=>{let spent=spentByCategory[b.category]||0,remaining=b.limitMinor-spent,pct=Math.min(100,Math.round(spent/b.limitMinor*100));return `<div class="budget-row"><b><span>${esc(b.category)}</span><span>${money(spent/100)} / ${money(b.limitMinor/100)}</span></b><small class="${remaining<0?'expense':'income'}">${remaining<0?money(Math.abs(remaining)/100)+' aşıldı':money(remaining/100)+' kaldı'}</small><div class="track"><i style="width:${pct}%"></i></div></div>`}).join(''):'<div class="budget-row"><b>Henüz bütçe yok</b><small>Bir kategori için aylık limit ekleyin.</small></div>';$('#goalsList').innerHTML=state.goals.length?state.goals.map(g=>{let pct=Math.min(100,Math.round(g.currentMinor/g.targetMinor*100));return `<div class="budget-row"><b><span>${esc(g.name)}</span><span>${pct}%</span></b><small>${money(g.currentMinor/100)} / ${money(g.targetMinor/100)}</small><div class="track"><i style="width:${pct}%"></i></div><button type="button" class="textButton" data-goal-contribution="${g.id}">Katkı ekle</button></div>`}).join(''):'<div class="budget-row"><b>Henüz birikim hedefi yok</b><small>Bir hedef ekleyerek ilerlemeni takip et.</small></div>'}
function renderCategories(txs,total){let grouped={};txs.filter(t=>txType(t)==='expense').forEach(t=>{let k=t.category||'Diğer';grouped[k]=(grouped[k]||0)+Math.abs(entryAmount(t.postings.find(p=>p.accountId==='expense')||{}))});let icons={Market:'🛒',Yemek:'☕',Ulaşım:'◉',Fatura:'⌁',Eğlence:'✦',Sağlık:'＋',Diğer:'·'};let rows=Object.entries(grouped).sort((a,b)=>b[1]-a[1]).slice(0,3);let empty='<div class="catRow"><span class="catIcon">✦</span><div><span class="catName">Henüz harcama yok</span><div class="catTrack"><i style="width:0"></i></div></div><span class="catValue">₺0</span></div>';$('#spendingCategories').innerHTML=rows.length?rows.map(([n,v])=>`<div class="catRow"><span class="catIcon">${icons[n]||'·'}</span><div><span class="catName">${esc(n)}</span><div class="catTrack"><i style="width:${total?v/total*100:0}%"></i></div></div><span class="catValue">${money(v)}</span></div>`).join(''):empty}
function recurringDueMinor(monthKey){let total=0;for(const recurring of state.recurring.filter(r=>r.active!==false)){let due=recurring.nextDueDate;for(let guard=0;guard<120&&due.slice(0,7)<=monthKey;guard++){if(due.slice(0,7)===monthKey)total+=recurring.amountMinor;due=FinanceCore.nextOccurrence(due,recurring.frequency)}}for(const debt of [...state.debts,...state.loans].filter(d=>d.active!==false)){for(let payment=0;payment<Math.min(600,Number(debt.remainingInstallments)||0);payment++){let due=FinanceCore.addMonths(debt.nextDueDate,payment);if(due.slice(0,7)===monthKey)total+=debt.direction==='incoming'?-debt.monthlyPaymentMinor:debt.monthlyPaymentMinor;if(due.slice(0,7)>monthKey)break}}return total}
function renderForecast(){const cashAccounts=state.accounts.filter(a=>isLiquidAccount(a)&&!a.archivedAt&&a.includeInTotals!==false);let html='',base=cashAccounts.reduce((n,a)=>n+accountBalance(a),0),max=1;let rows=[];for(let i=0;i<12;i++){let monthStart=FinanceCore.addMonths(dateISO().slice(0,8)+'01',i),key=monthStart.slice(0,7);let delta=state.transactions.filter(t=>t.planned&&t.date>dateISO()&&t.date.startsWith(key)).reduce((x,t)=>x+t.postings.filter(p=>cashAccounts.some(a=>a.id===p.accountId)).reduce((y,p)=>y+entryAmount(p),0),0)-recurringDueMinor(key)/100;base+=delta;rows.push({monthStart,base});max=Math.max(max,...rows.map(x=>Math.abs(x.base)))}for(const r of rows){let [y,m]=r.monthStart.split('-');html+=`<div class="month"><span>${new Date(Number(y),Number(m)-1,1).toLocaleDateString('tr-TR',{month:'short',year:'2-digit'})}</span><div class="bar"><i style="width:${Math.max(3,Math.abs(r.base)/max*100)}%"></i></div><b>${money(r.base)}</b></div>`}$('#forecast').innerHTML=html}
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmtDate=s=>new Date(s+'T12:00').toLocaleDateString('tr-TR');
function show(html,handler){$('#formContent').innerHTML=html;const m=$('#modal');$('#formContent').querySelectorAll('[onclick]').forEach(button=>{const action=button.getAttribute('onclick');button.removeAttribute('onclick');if(action.includes("document.getElementById('modal').close()"))button.onclick=()=>m.close();else if(action.includes('window.deleteCepFinansTransaction')){const match=action.match(/deleteCepFinansTransaction\('([^']+)'\)/);if(match)button.onclick=()=>window.deleteCepFinansTransaction(match[1])}else if(action.includes('window.duplicateCepFinansTransaction')){const match=action.match(/duplicateCepFinansTransaction\('([^']+)'\)/);if(match)button.onclick=()=>window.duplicateCepFinansTransaction(match[1])}else if(action.includes('window.archiveCepFinansAccount')){const match=action.match(/archiveCepFinansAccount\('([^']+)'\)/);if(match)button.onclick=()=>window.archiveCepFinansAccount(match[1])}else if(action.includes('window.openSplitTransactionForm'))button.onclick=()=>window.openSplitTransactionForm()});if(!m.open)m.showModal();$('#modalForm').onsubmit=async e=>{e.preventDefault();await handler(new FormData(e.target));m.close()}}
function accountForm(){show(`<h2 class="formTitle">Hesap ekle</h2><label class="field">Tür<select name="type"><option value="bank">Banka hesabı</option><option value="cash">Nakit cüzdan</option><option value="savings">Birikim hesabı</option><option value="wallet">Elektronik cüzdan</option><option value="prepaid">Ön ödemeli kart</option><option value="investment">Yatırım hesabı</option><option value="gold">Altın hesabı</option><option value="liability">Diğer yükümlülük</option><option value="card">Kredi kartı</option></select></label><label class="field">Hesap / kart adı<input required name="name" maxlength="80" placeholder="Örn. Garanti Vadesiz"></label><label class="field">Açılış bakiyesi (kart dışındaki hesaplar)<input name="opening" type="text" inputmode="decimal" value="0,00"></label><label class="field">Kart limiti (kredi kartı için)<input name="creditLimit" type="text" inputmode="decimal" value="0,00"></label><div class="formActions"><button>Kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async f=>{try{let type=f.get('type'),openingMinor=FinanceCore.minor(f.get('opening')||0),creditLimitMinor=FinanceCore.minor(f.get('creditLimit')||0),account={id:id(),schemaVersion:2,name:String(f.get('name')).trim(),type,currency:'TRY',opening:type==='card'?0:openingMinor/100,openingMinor:type==='card'?0:openingMinor};if(!account.name)throw new Error('Hesap adı gerekli.');if(type==='card')Object.assign(account,{creditLimitMinor,openingOutstandingMinor:0,expenseRecognition:'installment'});await put('accounts',account);await load();toast('Hesap eklendi')}catch(error){toast(error.message||'Hesap kaydedilemedi.')}})}
function editAccount(accountId){const account=state.accounts.find(a=>a.id===accountId);if(!account||account.archivedAt)return;const limit=((account.creditLimitMinor||0)/100).toFixed(2).replace('.',',');show(`<h2 class="formTitle">Hesabı düzenle</h2><label class="field">Hesap / kart adı<input required name="name" maxlength="80" value="${esc(account.name)}"></label><label class="field">Banka / kurum<input name="institution" maxlength="80" value="${esc(account.institution||'')}"></label>${account.type==='card'?`<label class="field">Kart limiti (TL)<input required name="creditLimit" type="text" inputmode="decimal" value="${limit}"></label><label class="field">Ekstre kesim günü (isteğe bağlı)<input name="closingDay" type="number" min="1" max="31" inputmode="numeric" value="${account.closingDay||''}"></label><p class="formHint">Son ödeme tarihi, kesim tarihinden otomatik olarak 10 gün sonrası hesaplanır.</p><label class="field">Kesim günündeki alışveriş sonraki ekstreye mi girer?<input name="closingDayPurchasesNext" type="checkbox" ${account.closingDayPurchasesNext?'checked':''}></label>`:''}<p class="formHint">Ekstre kesim günü boşsa uygulama ekstre borcu varsaymaz. Açılış bakiyesi geçmiş hesaplamaları korumak için burada değiştirilmez.</p><div class="formActions"><button>Kaydet</button><button type="button" onclick="window.archiveCepFinansAccount('${account.id}')">Arşivle</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async f=>{try{const name=String(f.get('name')||'').trim(),institution=String(f.get('institution')||'').trim();if(!name)throw new Error('Hesap adı gerekli.');let changes={...account,name,institution,updatedAt:dateISO()};if(account.type==='card'){const creditLimitMinor=FinanceCore.minor(f.get('creditLimit')),closingDay=Number(f.get('closingDay')||0);if(creditLimitMinor<0)throw new Error('Kart limiti negatif olamaz.');if(closingDay&&(!Number.isInteger(closingDay)||closingDay<1||closingDay>31))throw new Error('Kesim günü 1–31 arasında olmalı.');Object.assign(changes,{creditLimitMinor,closingDay:closingDay||null,dueOffsetDays:10,closingDayPurchasesNext:f.get('closingDayPurchasesNext')==='on'})}await put('accounts',changes);await load();toast('Hesap güncellendi')}catch(error){toast(error.message||'Hesap güncellenemedi.')}})}
async function archiveAccount(accountId){const account=state.accounts.find(a=>a.id===accountId);if(!account)return;if(!confirm(`${account.name} arşivlensin mi? Geçmiş hareketler korunur; hesap silinmez.`))return;await put('accounts',{...account,archivedAt:dateISO(),includeInTotals:false});$('#modal').close();await load();toast('Hesap arşivlendi')}
function budgetForm(){const categories=['Market','Yemek','Ulaşım','Fatura','Eğlence','Sağlık','Diğer'];show(`<h2 class="formTitle">Aylık bütçe ekle</h2><label class="field">Kategori<select name="category">${categories.map(c=>`<option>${c}</option>`).join('')}</select></label><label class="field">Aylık limit (TL)<input required name="limit" type="text" inputmode="decimal" placeholder="0,00"></label><div class="formActions"><button>Kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async f=>{try{let category=f.get('category'),limitMinor=FinanceCore.minor(f.get('limit'));if(limitMinor<=0)throw new Error('Limit sıfırdan büyük olmalı.');let existing=state.budgets.find(b=>b.category===category&&b.active!==false);await put('budgets',{...(existing||{}),id:existing?.id||id(),schemaVersion:1,category,limitMinor,period:'monthly',active:true,updatedAt:dateISO()});await load();toast('Bütçe kaydedildi')}catch(error){toast(error.message||'Bütçe kaydedilemedi.')}})}
