function goalContributionForm(goalId){const goal=state.goals.find(g=>g.id===goalId);if(!goal)return;show(`<h2 class="formTitle">Hedefe katkı ekle</h2><p class="formHint">Bu, birikim hedefi tahsisini günceller; banka bakiyesinde ayrıca değişiklik yapmaz. Para hareketini ayrıca kaydedin.</p><p class="formHint">${esc(goal.name)}: ${money(goal.currentMinor/100)} / ${money(goal.targetMinor/100)}</p><label class="field">Katkı tutarı (TL)<input required name="amount" type="text" inputmode="decimal" placeholder="0,00"></label><label class="field">Tarih<input required name="date" type="date" value="${dateISO()}"></label><div class="formActions"><button>Kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async f=>{try{const amountMinor=FinanceCore.minor(f.get('amount'));if(amountMinor<=0)throw new Error('Katkı tutarı sıfırdan büyük olmalı.');const currentMinor=goal.currentMinor+amountMinor;await put('savingsGoals',{...goal,currentMinor,status:currentMinor>=goal.targetMinor?'completed':'active',updatedAt:dateISO()});await put('goalContributions',{id:id(),schemaVersion:1,goalId,amountMinor,date:FinanceCore.date(f.get('date')),createdAt:dateISO()});await load();toast('Hedef katkısı kaydedildi')}catch(error){toast(error.message||'Katkı kaydedilemedi.')}})}
function recurringForm(){const activeAccounts=state.accounts.filter(a=>!a.archivedAt&&a.type!=='card');if(!activeAccounts.length){toast('Önce aktif bir banka hesabı ekleyin.');return}let accounts=activeAccounts.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('');show(`<h2 class="formTitle">Düzenli ödeme ekle</h2><label class="field">Ad<input required name="name" maxlength="80" placeholder="Örn. İnternet faturası"></label><label class="field">Tutar (TL)<input required name="amount" type="text" inputmode="decimal" placeholder="0,00"></label><label class="field">Kategori<select name="category"><option>Fatura</option><option>Yemek</option><option>Ulaşım</option><option>Diğer</option></select></label><label class="field">Ödeme hesabı<select name="accountId">${accounts}</select></label><label class="field">Sıklık<select name="frequency"><option value="monthly">Aylık</option><option value="weekly">Haftalık</option><option value="quarterly">3 aylık</option><option value="yearly">Yıllık</option></select></label><label class="field">İlk ödeme tarihi<input required name="nextDueDate" type="date" value="${dateISO()}"></label><div class="formActions"><button>Kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async f=>{try{let amountMinor=FinanceCore.minor(f.get('amount')),nextDueDate=FinanceCore.date(f.get('nextDueDate'));if(amountMinor<=0)throw new Error('Tutar sıfırdan büyük olmalı.');await put('recurringTransactions',{id:id(),schemaVersion:1,name:String(f.get('name')).trim(),amountMinor,category:f.get('category'),accountId:f.get('accountId'),frequency:f.get('frequency'),nextDueDate,active:true,postingPolicy:'manual'});await load();toast('Düzenli ödeme kaydedildi')}catch(error){toast(error.message||'Düzenli ödeme kaydedilemedi.')}})}
function txForm(mode=''){const activeAccounts=state.accounts.filter(a=>!a.archivedAt);if(!activeAccounts.length){toast('Önce aktif bir hesap veya kart ekleyin.');return}const opts=activeAccounts.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join(''),from=mode==='income'?'income':'',to=mode==='expense'?'expense':'';show(`<h2 class="formTitle">Yeni hareket</h2><label class="field">Tarih<input required name="date" type="date" value="${dateISO()}"></label><label class="field">Açıklama<input name="note" maxlength="140" placeholder="Örn. Market alışverişi"></label><label class="field">İş yeri / kişi (isteğe bağlı)<input name="payee" maxlength="100" placeholder="Örn. Migros"></label><label class="field">Etiketler (virgülle ayırın)<input name="tags" maxlength="160" placeholder="Örn. aile, zorunlu"></label><label class="field">Kategori<select name="category"><option>Market</option><option>Yemek</option><option>Ulaşım</option><option>Fatura</option><option>Eğlence</option><option>Sağlık</option><option selected>Diğer</option></select></label><label class="field">Kaynak<select required name="from"><option value="income" ${from?'selected':''}>Gelir</option>${opts}</select></label><label class="field">Hedef<select required name="to"><option value="expense" ${to?'selected':''}>Gider (harcama)</option>${opts}</select></label><label class="field">Tutar (TL)<input required name="amount" type="text" inputmode="decimal" placeholder="0,00"></label><label class="field">Kart taksiti (1 = peşin)<input name="installments" type="number" min="1" max="360" value="1" inputmode="numeric"></label><div class="formActions"><button>Kaydet</button><button type="button" onclick="window.openSplitTransactionForm()">Harcama böl</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,saveTx)}
async function saveTx(f){try{let from=f.get('from'),to=f.get('to'),totalMinor=FinanceCore.minor(f.get('amount')),n=Math.max(1,Number(f.get('installments'))||1),date=FinanceCore.date(f.get('date')),note=String(f.get('note')||'').trim(),payee=String(f.get('payee')||'').trim(),tags=String(f.get('tags')||'').split(',').map(tag=>tag.trim()).filter(Boolean).slice(0,12),category=f.get('category'),sourceAccount=state.accounts.find(a=>a.id===from);if(from===to){toast('Kaynak ve hedef farklı olmalı.');return}if(sourceAccount?.type==='card'&&to==='expense'&&n>1){await saveCardInstallmentPurchase({from,totalMinor,n,date,note,category,payee,tags});await load();toast(`${n} taksitli kart harcaması kaydedildi`);return}let installments=FinanceCore.split(totalMinor,n),groupId=n>1?id():null;for(let i=0;i<n;i++){let minor=installments[i],postings=FinanceCore.ledger([{accountId:from,amountMinor:-minor},{accountId:to,amountMinor:minor}]).map(p=>({...p,amount:p.amountMinor/100}));await put('transactions',{id:id(),schemaVersion:2,date:FinanceCore.addMonths(date,i),note:n>1?`${note} (${i+1}/${n})`:note,payee,tags,category,postings,planned:i>0,installmentGroup:groupId})}await load();toast(n>1?`${n} taksit planlandı`:'Hareket kaydedildi')}catch(error){toast(error.message||'Hareket kaydedilemedi.')}}
async function saveCardInstallmentPurchase(input){let purchaseId=id(),parts=FinanceCore.split(input.totalMinor,input.n),liability=FinanceCore.ledger([{accountId:input.from,amountMinor:-input.totalMinor},{accountId:'installmentPayable',amountMinor:input.totalMinor}]).map(p=>({...p,amount:p.amountMinor/100}));await put('transactions',{id:purchaseId,schemaVersion:2,type:'cardPurchase',date:input.date,note:input.note,payee:input.payee,tags:input.tags,category:input.category,postings:liability,planned:false,installmentGroup:purchaseId});let installments=[];for(let i=0;i<parts.length;i++){let dueDate=FinanceCore.addMonths(input.date,i),minor=parts[i],postings=FinanceCore.ledger([{accountId:'installmentPayable',amountMinor:-minor},{accountId:'expense',amountMinor:minor}]).map(p=>({...p,amount:p.amountMinor/100})),installment={id:id(),purchaseId,dueDate,amountMinor:minor,status:i===0&&dueDate<=dateISO()?'posted':'planned'};installments.push(installment);await put('transactions',{id:installment.id,schemaVersion:2,type:'installmentExpense',date:dueDate,note:`${input.note} (${i+1}/${parts.length})`,payee:input.payee,tags:input.tags,category:input.category,postings,planned:installment.status!=='posted',installmentGroup:purchaseId})}await put('cardPurchases',{id:purchaseId,cardAccountId:input.from,purchaseDate:input.date,note:input.note,payee:input.payee,tags:input.tags,category:input.category,totalMinor:input.totalMinor,remainingMinor:input.totalMinor,installments,expenseRecognition:'installment',status:'active'})}
async function deleteInstallmentGroup(groupId){const count=state.transactions.filter(t=>t.installmentGroup===groupId).length;if(!confirm(`Bu taksit grubundaki ${count} kayıt silinsin mi? Kart borcu ve planlanan taksitler buna göre yeniden hesaplanır.`))return;for(const transaction of state.transactions.filter(t=>t.installmentGroup===groupId))await remove('transactions',transaction.id);await remove('cardPurchases',groupId);await load();toast('Taksit grubu silindi')}
function editTransaction(idValue){let original=state.transactions.find(t=>t.id===idValue);if(!original)return;if(original.installmentGroup){deleteInstallmentGroup(original.installmentGroup);return}let from=original.postings[0]?.accountId,to=original.postings[1]?.accountId,amount=Math.abs(entryAmount(original.postings.find(p=>p.accountId==='expense'||p.accountId==='income')||original.postings[0]||{})).toFixed(2).replace('.',','),categories=['Market','Yemek','Ulaşım','Fatura','Eğlence','Sağlık','Diğer'],accountOptions=state.accounts.map(a=>`<option value="${a.id}" ${a.id===from?'selected':''}>${esc(a.name)}</option>`).join(''),targetOptions=state.accounts.map(a=>`<option value="${a.id}" ${a.id===to?'selected':''}>${esc(a.name)}</option>`).join('');show(`<h2 class="formTitle">Hareketi düzenle</h2><label class="field">Tarih<input required name="date" type="date" value="${original.date}"></label><label class="field">Açıklama<input name="note" maxlength="140" value="${esc(original.note||'')}"></label><label class="field">İş yeri / kişi<input name="payee" maxlength="100" value="${esc(original.payee||'')}"></label><label class="field">Etiketler (virgülle ayırın)<input name="tags" maxlength="160" value="${esc((original.tags||[]).join(', '))}"></label><label class="field">Kategori<select name="category">${categories.map(c=>`<option ${c===(original.category||'Diğer')?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">Kaynak<select required name="from"><option value="income" ${from==='income'?'selected':''}>Gelir</option>${accountOptions}</select></label><label class="field">Hedef<select required name="to"><option value="expense" ${to==='expense'?'selected':''}>Gider (harcama)</option>${targetOptions}</select></label><label class="field">Tutar (TL)<input required name="amount" type="text" inputmode="decimal" value="${amount}"></label><div class="formActions"><button>Kaydet</button><button type="button" onclick="window.duplicateCepFinansTransaction('${original.id}')">Kopyala</button><button type="button" onclick="window.deleteCepFinansTransaction('${original.id}')">Sil</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async f=>{try{let source=f.get('from'),target=f.get('to'),amountMinor=FinanceCore.minor(f.get('amount')),payee=String(f.get('payee')||'').trim(),tags=String(f.get('tags')||'').split(',').map(tag=>tag.trim()).filter(Boolean).slice(0,12);if(source===target)throw new Error('Kaynak ve hedef farklı olmalı.');let postings=FinanceCore.ledger([{accountId:source,amountMinor:-amountMinor},{accountId:target,amountMinor}]).map(p=>({...p,amount:p.amountMinor/100}));await put('transactions',{...original,date:FinanceCore.date(f.get('date')),note:String(f.get('note')||'').trim(),payee,tags,category:f.get('category'),postings,schemaVersion:2});await load();toast('Hareket güncellendi')}catch(error){toast(error.message||'Hareket güncellenemedi.')}})}
async function duplicateTransaction(idValue){const original=state.transactions.find(t=>t.id===idValue);if(!original)return;const copy={...original,id:id(),date:dateISO(),note:original.note?`${original.note} (kopya)`:'Kopya hareket',planned:false,installmentGroup:null,splitGroup:null,createdAt:dateISO()};await put('transactions',copy);$('#modal').close();await load();toast('Hareket bugünün tarihiyle kopyalandı')}
async function deleteTransaction(idValue){if(!confirm('Bu hareket silinsin mi? Bu işlem geri alınamaz.'))return;await remove('transactions',idValue);$('#modal').close();await load();toast('Hareket silindi')}
function pages(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{if(!b.dataset.page)return;document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id===b.dataset.page));document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('selected',x.dataset.page===b.dataset.page))})}
async function backup(){const snapshot={version:3,createdAt:new Date().toISOString()};for(const storeName of BACKUP_STORES)snapshot[storeName]=storeName==='accounts'?state.accounts:storeName==='transactions'?state.transactions:await all(storeName);if(!BACKUP_STORES.some(storeName=>snapshot[storeName].length)){toast('Yedeklenecek kayıt yok.');return}let pass=prompt('Yedek parolasını belirleyin. Bu parola olmadan geri yüklenemez.');if(!pass)return;let confirm=prompt('Parolayı tekrar girin.');if(pass!==confirm){toast('Parolalar eşleşmiyor.');return}let salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await derive(pass,salt),plain=new TextEncoder().encode(JSON.stringify(snapshot)),encrypted=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,plain),data={format:'cep-finans-backup',version:3,kdf:'PBKDF2-SHA-256',iterations:250000,salt:b64(salt),iv:b64(iv),ciphertext:b64(new Uint8Array(encrypted))};download(JSON.stringify(data),'cep-finans-yedek-'+dateISO()+'.cepfinans');toast('Tüm verileri içeren şifreli yedek indirildi')}
async function derive(pass,salt){let material=await crypto.subtle.importKey('raw',new TextEncoder().encode(pass),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:250000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
function b64(a){return btoa(String.fromCharCode(...a))}function unb64(s){return Uint8Array.from(atob(s),c=>c.charCodeAt(0))}function download(text,name){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportCsv(){const quote=value=>`"${String(value??'').replace(/"/g,'""')}"`,rows=[['Tarih','Açıklama','Kategori','Tür','Kaynak','Hedef','Tutar (TL)','Planlı']];for(const t of state.transactions){let source=t.postings.find(p=>entryAmount(p)<0),target=t.postings.find(p=>entryAmount(p)>0),amount=Math.abs(entryAmount(source||target||{})),type=txType(t);rows.push([t.date,t.note||'',t.category||'',type,accountName(source?.accountId),accountName(target?.accountId),amount.toFixed(2).replace('.',','),t.planned?'Evet':'Hayır'])}const csv='\uFEFF'+rows.map(row=>row.map(quote).join(';')).join('\r\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`cep-finans-hareketler-${dateISO()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('CSV dışa aktarıldı')}
async function restore(file){try{let x=JSON.parse(await file.text());if(x.format!=='cep-finans-backup'||!Number.isInteger(x.version)||x.version>3)throw Error();let pass=prompt('Yedek parolası:');if(!pass)return;let plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(x.iv)},await derive(pass,unb64(x.salt)),unb64(x.ciphertext));let d=JSON.parse(new TextDecoder().decode(plain));if(!Array.isArray(d.accounts)||!Array.isArray(d.transactions))throw Error();for(const storeName of BACKUP_STORES)if(!Array.isArray(d[storeName]))d[storeName]=[];let recordCount=BACKUP_STORES.reduce((total,storeName)=>total+d[storeName].length,0);if(!confirm(`Bu işlem yedekteki ${recordCount} kaydı geri yükler ve bu uygulamadaki mevcut kayıtların yerini alır. Devam edilsin mi?`))return;await replaceCoreData(d);await load();toast('Yedek güvenle geri yüklendi')}catch(e){toast('Yedek açılamadı: parola veya dosya hatalı.')}$('restoreFile').value=''}
async function init(){await openDB();pages();const txSearch=document.createElement('input');txSearch.type='search';txSearch.placeholder='Hareket ara';txSearch.setAttribute('aria-label','Hareket ara');txSearch.style.cssText='width:100%;margin-top:9px;padding:10px 12px;border-radius:12px;border:1px solid #ffffff18;background:#ffffff0d;color:inherit';txSearch.addEventListener('input',e=>{txQuery=e.target.value;render()});$('#txFilters').append(txSearch);window.addEventListener('online',announceConnection);window.addEventListener('offline',announceConnection);window.deleteCepFinansTransaction=deleteTransaction;window.duplicateCepFinansTransaction=duplicateTransaction;window.archiveCepFinansAccount=archiveAccount;window.openSplitTransactionForm=splitTransactionForm;document.addEventListener('click',e=>{const item=e.target.closest('[data-edit-id]');if(item){editTransaction(item.dataset.editId);return}const account=e.target.closest('[data-account-id]');if(account){editAccount(account.dataset.accountId);return}const goal=e.target.closest('[data-goal-contribution]');if(goal){goalContributionForm(goal.dataset.goalContribution);return}const recurringEdit=e.target.closest('[data-recurring-edit]');if(recurringEdit){editRecurringForm(recurringEdit.dataset.recurringEdit);return}const recurring=e.target.closest('[data-recurring-post]');if(recurring){postRecurringForm(recurring.dataset.recurringPost);return}const debt=e.target.closest('[data-debt-settle]');if(debt){settleDebtForm(debt.dataset.debtSettle);return}if(e.target.closest('[data-debt-form]'))debtForm()});$('#newAccount').onclick=accountForm;$('#newBudget').onclick=budgetForm;$('#newGoal').onclick=goalForm;$('#newRecurring').onclick=recurringForm;$('#newTx').onclick=txForm;$('#fab').onclick=txForm;document.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>txForm(b.dataset.quick));document.querySelectorAll('#txFilters button').forEach(b=>b.onclick=()=>{txFilter=b.dataset.filter;document.querySelectorAll('#txFilters button').forEach(x=>x.classList.toggle('active',x===b));render()});$('#backupBtn').onclick=backup;$('#csvExportBtn').onclick=exportCsv;$('#restoreFile').onchange=e=>e.target.files[0]&&restore(e.target.files[0]);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js?v=20');await load();if(!navigator.onLine)announceConnection()}init().catch(e=>{console.error(e);toast('Uygulama deposu açılamadı.')});
